Let me understand the requirements:

1. Implement `open_client`, `client_put`, `client_get` tools
2. Each `client_id` owns an independent key/value map
3. A value written by client a must be unavailable to client b (isolation)
4. Require non-empty strings
5. Reject unknown clients
6. Reject unknown tools
7. Run the tests

Let me design the implementation:

- Maintain a `Map` of clients, where each client has its own `Map` of key/value.
- `open_client`: takes `client_id` (non-empty string), creates an empty map for that client.
- `client_put`: takes `client_id`, `key`, `value` (all non-empty strings). The client must be known (opened). Stores key/value in that client's map.
- `client_get`: takes `client_id`, `key` (non-empty strings). Client must be known. Returns the value if found. If not found, reject (throw error - test uses `assert.rejects`).

For `listTools`, I need to return the tools with inputSchemas including `additionalProperties: false`.

For `callTool`, if the tool name is unknown, throw an error.

Let me check the test:
```js
await callTool('open_client',{client_id:'a'});
await callTool('open_client',{client_id:'b'});
await callTool('client_put',{client_id:'a',key:'k',value:'v'});
await assert.rejects(()=>callTool('client_get',{client_id:'b',key:'k'}))
```

So after putting `k=v` for client `a`, getting `k` from client `b` should reject (because `b` doesn't have `k`).

Let me write the server.mjs:

```js
const clients = new Map(); // client_id -> Map(key -> value)

function isNonEmptyString(s) {
  return typeof s === 'string' && s.length > 0;
}

export async function listTools() {
  return [
    {
      name: 'open_client',
      description: 'Open a new client with an isolated key/value map.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' }
        },
        required: ['client_id'],
        additionalProperties: false
      }
    },
    {
      name: 'client_put',
      description: 'Store a key/value pair for the given client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' }
        },
        required: ['client_id', 'key', 'value'],
        additionalProperties: false
      }
    },
    {
      name: 'client_get',
      description: 'Retrieve a value for a key owned by the given client.',
      inputSchema: {
        type: 'object',
        properties: {
          client_id: { type: 'string' },
          key: { type: 'string' }
        },
        required: ['client_id', 'key'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'open_client': {
      const { client_id } = args;
      if (!isNonEmptyString(client_id)) {
        throw new Error('client_id must be a non-empty string');
      }
      if (!clients.has(client_id)) {
        clients.set(client_id, new Map());
      }
      return { content: [{ type: 'text', text: JSON.stringify({ client_id, opened: true }) }] };
    }
    case 'client_put': {
      const { client_id, key, value } = args;
      if (!isNonEmptyString(client_id)) {
        throw new Error('client_id must be a non-empty string');
      }
      if (!isNonEmptyString(key)) {
        throw new Error('key must be a non-empty string');
      }
      if (!isNonEmptyString(value)) {
        throw new Error('value must be a non-empty string');
      }
      if (!clients.has(client_id)) {
        throw new Error('unknown client: ' + client_id);
      }
      clients.get(client_id).set(key, value);
      return { content: [{ type: 'text', text: JSON.stringify({ client_id, key, value, stored: true }) }] };
    }
    case 'client_get': {
      const { client_id, key } = args;
      if (!isNonEmptyString(client_id)) {
        throw new Error('client_id must be a non-empty string');
      }
      if (!isNonEmptyString(key)) {
        throw new Error('key must be a non-empty string');
      }
      if (!clients.has(client_id)) {
        throw new Error('unknown client: ' + client_id);
      }
      const store = clients.get(client_id);
      if (!store.has(key)) {
        throw new Error('unknown key: ' + key);
      }
      return { content: [{ type: 'text', text: JSON.stringify({ client_id, key, value: store.get(key) }) }] };
    }
    default:
      throw new Error('Unknown tool: ' + name);
  }
}
```

This should satisfy the requirements:
- Each client owns an independent map (isolation by client_id).
- A value written by client a is unavailable to client b (b's store doesn't have the key, so it rejects).
- Non-empty strings required.
- Reject unknown clients (client_put/client_get check `clients.has`).
- Reject unknown tools (default case throws).

